fn is_palindrome(s: &str) -> bool {
    // Filtrar solo caracteres alfanuméricos y convertir a minúsculas para ignorar mayúsculas/minúsculas
    let filtered: String = s.chars()
        .filter(|c| c.is_alphanumeric())
