fn eval_rpn(expr: &str) -> Result<i64, String> {
    let tokens = expr.split_whitespace().filter_map(|s| s.parse::<i64>().ok());
    let mut stack: Vec<i64> = Vec::new();

    for token in tokens {
        match token {
            // Operadores
            "+" => {
                if stack.len() >= 2 {
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    stack.push(a + b);
                } else {
                    return Err("not enough operands".to_string());
                }
            }
            "-" => {
                if stack.len() >= 2 {
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    stack.push(a - b);
                } else {
                    return Err("not enough operands".to_string());
                }
            }
            "*" => {
                if stack.len() >= 2 {
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    stack.push(a * b);
                } else {
                    return Err("not enough operands".to_string());
                }
            }
            "/" => {
                if stack.len() >= 2 {
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    if b == 0 {
                        return Err("division by zero".to_string());
                    }
                    stack.push(a / b);
                } else {
                    return Err("not enough operands".to_string());
                }
            }
            _ => {
                // If token is a number (we already parsed it), push it
                stack.push(token);
            }
        }
    }

    // At the end, there should be exactly one value left on the stack
    if stack.len() != 1 {
        let result = stack.pop().unwrap();
        // If we have more than one, it means there were extra values
        if stack.len() > 1 {
            let extra = stack.iter().take(stack.len() - 1).collect::<Vec<_>>().join(", ");
            return Err(format!("extra values: {}", extra));
        }
    }

    Ok(stack.pop().unwrap())
}
