use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;

fn parallel_sum(data: &[u64], threads: usize) -> u64 {
    let n = data.len();
    if n == 0 {
        return 0;
    }
    let num_threads = if threads == 0 { 1 } else { threads };

    // Calcular el tamaño de cada bloque para distribuir los elementos
