    let total = Arc::new(AtomicU64::new(0));

    thread::scope(|s| {
        for i in 0..num_threads {
            let start = i * block_size;
            let end = std::cmp::min(start + block_size, n);
            s.spawn(move || {
                // Extraer el subslice correspondiente
                let chunk: Vec<u64> = data[start..end].to_vec();
