                let sum_chunk: u64 = chunk.iter().map(|&x| x as u64).sum();
                // Acumular en el contador atómico
                total.load(Ordering::Relaxed).fetch_add(sum_chunk, Ordering::Relaxed);
            });
        }
    });

    // Obtener el valor final de la suma total
    total.load(Ordering::Relaxed)
}
