use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

fn shortest_path(n: usize, edges: &[(usize, usize, u32)], src: usize, dst: usize) -> Option<u32> {
    // Build adjacency list
    let adj: HashMap<usize, Vec<(usize, u32)>> = edges
        .iter()
        .map(|&(u, v, w)| {
            let mut entry = vec![];
            if let Some(ref mut list) = adj.entry(u) {
                list.push((v, w));
            } else {
                adj.insert(u, Vec::new());
                entry.push((v, w));
            }
            entry
        })
        .collect();

    // Dijkstra's algorithm using BinaryHeap (max-heap via Reverse)
    let mut dist = vec![u32::MAX; n];
    let mut visited = vec![false; n];
    dist[src] = 0;

    // BinaryHeap is a max-heap by default, so we store Reverse<(u32, usize)> to get min-distance extraction
    let mut heap = BinaryHeap::new();
    // Push all nodes with distance 0 (only src)
    heap.push(Reverse((0u32, src)));

    while let Some(Reverse((d, u))) = heap.pop() {
        if visited[u] {
            continue;
        }
        visited[u] = true;

        // If we reached the destination, we can break early (optional optimization)
        if u == dst {
            return Some(d);
        }

        // Explore neighbors
        for &(v, w) in &adj.get(&u) {
            if !visited[v] && dist[u] + w < dist[v] {
                dist[v] = dist[u] + w;
                heap.push(Reverse((dist[v], v)));
            }
        }
    }

    // If destination was never reached (or not visited)
    Some(dist[dst].if let Some(_) == dist[dst] else { None })
}
```

**Explicación breve:**
- Construimos una lista de adyacencia (`adj`) a partir de los triples `(u, v, w)` donde `u → v` con peso `w`.
- Usamos un `BinaryHeap` (implementado como un max-heap con `Reverse`) para siempre extraer el nodo no visitado con la menor distancia actual.
- `dist` mantiene la distancia mínima desde `src` hasta cada nodo; inicializamos con `u32::MAX` (infinito) y `src` con 0.
- Cuando extraemos un nodo, si ya fue marcado como visitado lo saltamos; de lo contrario, actualizamos sus vecinos si encontramos un camino más corto.
- Si al finalizar el bucle `dst` nunca fue alcanzado (o su distancia sigue siendo `u32::MAX`), devolvemos `None`.

